private bool EnableBulletCamFromShotData(ShotDataStruct shotData)
	{
		// Enable for all headshots
		if(shotData.Headshot == true && UnityEngine.Random.value < 0.3f)
			return true;

		Dictionary<HealthComponent, SimulateShotResults> results = shotData.Results;

		// Loop over results health components and see if any have bullet cam enabled
		foreach(KeyValuePair<HealthComponent, SimulateShotResults> kvp in results)
		{
			if(kvp.Key.BulletCamOnHit == true)
				return true;
		}

		return false;
	}

private bool EnableBulletCamFromShotData(ShotDataStruct shotData)
	{
		// Enable for all headshots
		if(shotData.Headshot == true && UnityEngine.Random.value < 0.3f)
			return true;

		Dictionary<HealthComponent, SimulateShotResults> results = shotData.Results;

		// Loop over results health components and see if any have bullet cam enabled
		foreach(KeyValuePair<HealthComponent, SimulateShotResults> kvp in results)
		{
			if(kvp.Key.BulletCamOnHit == true)
				return true;
		}

		return false;
	}

