def generate\_rss():
 # Parse the RSS feed
 feed = feedparser.parse(rss\_url)

 new\_rss = """xml version="1.0" encoding="UTF-8"?
{title}
{link}
 {description}
{language}
 """.format(title=feed.feed.title, link=feed.feed.link, description=feed.feed.description, language=feed.feed.language)

