class ArithmeticParser < Racc::Parser
 rule
 # Existing rules for add, subtract, multiply, divide, negate, number, and identifier
 expression : term '+' expression { [:add, value[0], value[2]] }
 | term '-' expression { [:subtract, value[0], value[2]] }
 | term

 term : factor '\*' term { [:multiply, value[0], value[2]] }
 | factor '/' term { [:divide, value[0], value[2]] }
 | factor

 factor : exponentiation { value }
 | number { [:number, value.to\_i] }
 | '(' expression ')' { value[1] }
 | '-' factor { [:negate, value[1]] }

 # New rule for exponentiation and nth roots
 exponentiation : function { value }
 | factor '^' exponentiation { [:exponentiate, value[0], value[2]] }

 root : function '√' number { [:nth\_root, value[0], value[2]] }

 # New rules for function calls and formula names
 aggregate\_function : 'sum' | 'average' | 'min' | 'max' | 'stdev' | 'variance'

 selection\_criteria : '(' expression ',' expression ')' { [value[1], value[3]] }

 column\_name : column\_name\_token

 column\_name\_token : { /[a-zA-Z]+/ }

 table\_name : table\_name\_token

 table\_name\_token : { /[a-zA-Z\_]+/ }

 data\_source\_name : table\_name '.' column\_name selection\_criteria { [:data\_source, value[0], value[1], value[2]] }
 | table\_name '.' column\_name { [:data\_source, value[0], value[1], []] }

 function : aggregate\_function '(' expression ')' { [:aggregate\_function, value[0], value[2]] }
 | function\_name '(' expression ')' { [:function\_call, value[0], value[2]] }
 | formula\_name { [:formula\_name, value[0]] }
 | data\_source\_name { value[0] }

 formula\_name : formula\_name\_token { value[0] }

 formula\_name\_token : { /[a-zA-Z\_][a-zA-Z0-9\_]\*/ }
end

