open class TripDataSyncTask(private val application: Application) : AsyncTask() {

 enum class Status { SUCCESS, CANCELLED, ABORTED }

 companion object {
 private val TAG = TripDataSyncTask::class.java.simpleName
 }

 override fun doInBackground(vararg params: Any?): Status {
 Log.d(TAG, "Starting work")
 val mode = MyPNR.getInstance().mode

 //TODO handle this by changing scheduling condition of the Job according to the user's preferences
 if (mode == MyPNR.Mode.TRAIN) {
 val userWifiPref: Boolean = params[0] as Boolean
 val userDataPref: Boolean = params[1] as Boolean

 if (!userDataPref && NetworkUtils.isConnectedMobile(application)) {
 Log.d(TAG, "Stopping work because mobile data not available")
 return Status.CANCELLED
 }

 if (!userWifiPref && NetworkUtils.isConnectedWifi(application)) {
 Log.d(TAG, "Stopping work because wifi not available")
 return Status.CANCELLED
 }
 }

 val activeTrips = ItineraryHelper.getActiveTrips(application, TravelItinerary::class.java)

 Log.d(TAG, "Active Trips : ${activeTrips.size}")

 if (isCancelled) return Status.ABORTED

 val tripsToBeHandled = getTripsToBeHandled(activeTrips.toMutableList())

 Log.d(TAG, "Trips to be handled : ${tripsToBeHandled.size}")

 for (trip in tripsToBeHandled) {
 Log.i(TAG, "Handling PNR: " + trip.pnr)
 NotificationHandler.handleChain(application, trip)
 if (isCancelled) return Status.ABORTED
 }

 val syncHelper = TripSyncHelper(application)
 if (mode == MyPNR.Mode.FLIGHT) {
 syncHelper.sync()
 } else if (mode == MyPNR.Mode.TRAIN && IxiAuth.getInstance().isLoggedIn) {
 syncHelper.sync(Constant.INTERVAL\_TWO\_HOURS)
 }

 return Status.SUCCESS
 }

 // Filters out trips that required handling
 private fun getTripsToBeHandled(activeTrips: MutableList): List =
 activeTrips.map { it as TravelItinerary }.filter { isRefreshRequired(it) }

 private fun isRefreshRequired(trip: TravelItinerary): Boolean {

 try {
 if (trip.lastUpdated == null) {
 return true
 }

 val timeSinceLastCheck = System.currentTimeMillis() - trip.lastUpdated.time
 val timeTillJourney = trip.journeyDate.time - System.currentTimeMillis()

 if (timeSinceLastCheck < Constant.MIN\_ELAPSED\_TIME\_BEFORE\_RESYNC) {
 return false
 }

 if (!trip.isCanceled) {
 if (timeTillJourney >= Constant.INTERVAL\_ONE\_WEEK) {
 if (timeSinceLastCheck >= Constant.INTERVAL\_TWELVE\_HOURS) {
 return true
 }
 } else if (timeTillJourney >= Constant.INTERVAL\_TWO\_DAYS) {
 if (timeSinceLastCheck >= Constant.INTERVAL\_SIX\_HOURS) {
 return true
 }
 } else if (timeTillJourney >= Constant.INTERVAL\_ONE\_HOUR) {
 if (timeSinceLastCheck >= Constant.INTERVAL\_FORTY\_FIVE\_MINUTES) {
 return true
 }
 }

 }

 return false
 } catch (e: Exception) {
 e.printStackTrace()
 return true
 }

 }
}

