function handleProgressBar() {
const progressBarFilled = document.querySelector(‘.progress-bar-filled’);
if (isGenerating || isFirstGeneration) {
if (isFirstGeneration) {
startTime = Date.now();
isFirstGeneration = false;
progressBarFilled.innerText = ‘loading’;
} else {
const currentTime = Date.now();
const secondsPassed = Math.floor((currentTime - previousGenerationTime) / 1000);
progressBarFilled.innerText = done: ${secondsPassed} sec;
}
previousGenerationTime = Date.now();
} else {
progressBarFilled.innerText = ‘’;
}
}
