    std::cout << "arr: ";
    printArr(a, n);
    maxCount(a, n, max, count);
    std::cout << "\nmax: " << max;
    std::cout << "\ncount: " << count;

}


void initArr(int(&a)[N], int n) {
    for (int i = 0; i < n; ++i) a[i] = rand() % 11;
}

void printArr(const int(&a)[N], int n) {
    for (int i = 0; i < n; ++i) std::cout << a[i] << " ";
}

int maxCount(const int(&a)[N], int n, int& max, int& count) {
    for (int i = 1; i < N; ++i) {
        if (a[i] > max) {
            max = a[i];
            count = 1;
        }
        else if (a[i] == max) count++;
    }
    return (max, count);
}

